/// Every notification in the protocol, by method name.
pub const NotificationMethod = enum {
    @"$/cancelRequest",
    @"$/logTrace",
    @"$/progress",
    @"$/setTrace",
    /// The exit event is sent from the client to the server to
    /// ask the server to exit its process.
    exit,
    /// The initialized notification is sent from the client to the
    /// server after the client is fully initialized and the server
    /// is allowed to send requests from the server to the client.
    initialized,
    @"notebookDocument/didChange",
    /// A notification sent when a notebook closes.
    ///
    /// Since LSP 3.17.0.
    @"notebookDocument/didClose",
    /// A notification sent when a notebook opens.
    ///
    /// Since LSP 3.17.0.
    @"notebookDocument/didOpen",
    /// A notification sent when a notebook document is saved.
    ///
    /// Since LSP 3.17.0.
    @"notebookDocument/didSave",
    /// The telemetry event notification is sent from the server to the client to ask
    /// the client to log telemetry data.
    @"telemetry/event",
    /// The document change notification is sent from the client to the server to signal
    /// changes to a text document.
    @"textDocument/didChange",
    /// The document close notification is sent from the client to the server when
    /// the document got closed in the client. The document's truth now exists where
    /// the document's uri points to (e.g. if the document's uri is a file uri the
    /// truth now exists on disk). As with the open notification the close notification
    /// is about managing the document's content. Receiving a close notification
    /// doesn't mean that the document was open in an editor before. A close
    /// notification requires a previous open notification to be sent.
    @"textDocument/didClose",
    /// The document open notification is sent from the client to the server to signal
    /// newly opened text documents. The document's truth is now managed by the client
    /// and the server must not try to read the document's truth using the document's
    /// uri. Open in this sense means it is managed by the client. It doesn't necessarily
    /// mean that its content is presented in an editor. An open notification must not
    /// be sent more than once without a corresponding close notification send before.
    /// This means open and close notification must be balanced and the max open count
    /// is one.
    @"textDocument/didOpen",
    /// The document save notification is sent from the client to the server when
    /// the document got saved in the client.
    @"textDocument/didSave",
    /// Diagnostics notification are sent from the server to the client to signal
    /// results of validation runs.
    @"textDocument/publishDiagnostics",
    /// A document will save notification is sent from the client to the server before
    /// the document is actually saved.
    @"textDocument/willSave",
    /// The log message notification is sent from the server to the client to ask
    /// the client to log a particular message.
    @"window/logMessage",
    /// The show message notification is sent from a server to a client to ask
    /// the client to display a particular message in the user interface.
    @"window/showMessage",
    /// The `window/workDoneProgress/cancel` notification is sent from  the client to the server to cancel a progress
    /// initiated on the server side.
    @"window/workDoneProgress/cancel",
    /// The configuration change notification is sent from the client to the server
    /// when the client's configuration has changed. The notification contains
    /// the changed configuration as defined by the language client.
    @"workspace/didChangeConfiguration",
    /// The watched files notification is sent from the client to the server when
    /// the client detects changes to file watched by the language client.
    @"workspace/didChangeWatchedFiles",
    /// The `workspace/didChangeWorkspaceFolders` notification is sent from the client to the server when the workspace
    /// folder configuration changes.
    @"workspace/didChangeWorkspaceFolders",
    /// The did create files notification is sent from the client to the server when
    /// files were created from within the client.
    ///
    /// Since LSP 3.16.0.
    @"workspace/didCreateFiles",
    /// The will delete files request is sent from the client to the server before files are actually
    /// deleted as long as the deletion is triggered from within the client.
    ///
    /// Since LSP 3.16.0.
    @"workspace/didDeleteFiles",
    /// The did rename files notification is sent from the client to the server when
    /// files were renamed from within the client.
    ///
    /// Since LSP 3.16.0.
    @"workspace/didRenameFiles",
};

/// Static facts about a notification: its params, registration options, direction and the LSP version that introduced it.
pub fn NotificationInfo(comptime m: NotificationMethod) type {
    return switch (m) {
        .@"$/cancelRequest" => struct {
            pub const Params = CancelParams;
            pub const RegistrationOptions = void;
            pub const direction: Direction = .both;
            pub const since: ?[]const u8 = null;
            pub const registration_method: ?[]const u8 = null;
            pub const client_capability: ?[]const u8 = null;
            pub const server_capability: ?[]const u8 = null;
        },
        .@"$/logTrace" => struct {
            pub const Params = LogTraceParams;
            pub const RegistrationOptions = void;
            pub const direction: Direction = .server_to_client;
            pub const since: ?[]const u8 = null;
            pub const registration_method: ?[]const u8 = null;
            pub const client_capability: ?[]const u8 = null;
            pub const server_capability: ?[]const u8 = null;
        },
        .@"$/progress" => struct {
            pub const Params = ProgressParams;
            pub const RegistrationOptions = void;
            pub const direction: Direction = .both;
            pub const since: ?[]const u8 = null;
