/// A special text edit with an additional change annotation.
///
/// Since LSP 3.16.0..
pub const AnnotatedTextEdit = struct {
    /// The range of the text document to be manipulated. To insert
    /// text into a document create a range where start === end.
    range: Range,
    /// The string to be inserted. For delete operations use an
    /// empty string.
    newText: []const u8,
    /// The actual identifier of the change annotation
    annotationId: ChangeAnnotationIdentifier,
    pub fn jsonStringify(self: @This(), w: *std.json.Stringify) std.json.Stringify.Error!void {
        return json.writeStruct(self, w, &.{});
    }
};

/// Defines how values from a set of defaults and an individual item will be
/// merged.
///
/// Since LSP 3.18.0.
pub const ApplyKind = enum(u32) {
    /// The value from the individual item (if provided and not `null`) will be
    /// used instead of the default.
    Replace = 1,
    /// The value from the item will be merged with the default.
    Merge = 2,
    _,
    pub const json_integer = true;
    pub fn jsonStringify(self: @This(), w: *std.json.Stringify) std.json.Stringify.Error!void {
        return json.writeIntEnum(self, w);
    }
};

/// The parameters passed via an apply workspace edit request.
pub const ApplyWorkspaceEditParams = struct {
    /// An optional label of the workspace edit. This label is
    /// presented in the user interface for example on an undo
    /// stack to undo the workspace edit.
    label: ?[]const u8 = null,
    /// The edits to apply.
    edit: WorkspaceEdit,
    /// Additional data about the edit.
    ///
    /// Since LSP 3.18.0.
    metadata: ?WorkspaceEditMetadata = null,
    pub fn jsonStringify(self: @This(), w: *std.json.Stringify) std.json.Stringify.Error!void {
        return json.writeStruct(self, w, &.{});
    }
};

/// The result returned from the apply workspace edit request.
///
/// Since LSP 3.17 renamed from ApplyWorkspaceEditResponse
pub const ApplyWorkspaceEditResult = struct {
    /// Indicates whether the edit was applied or not.
    applied: bool,
    /// An optional textual description for why the edit was not applied.
    /// This may be used by the server for diagnostic logging or to provide
    /// a suitable error for a request that triggered the edit.
    failureReason: ?[]const u8 = null,
    /// Depending on the client's failure handling strategy `failedChange` might
    /// contain the index of the change that failed. This property is only available
    /// if the client signals a `failureHandlingStrategy` in its client capabilities.
    failedChange: ?u32 = null,
    pub fn jsonStringify(self: @This(), w: *std.json.Stringify) std.json.Stringify.Error!void {
        return json.writeStruct(self, w, &.{});
    }
};

/// A base for all symbol information.
pub const BaseSymbolInformation = struct {
    /// The name of this symbol.
    name: []const u8,
    /// The kind of this symbol.
    kind: SymbolKind,
    /// Tags for this symbol.
    ///
    /// Since LSP 3.16.0.
    tags: ?[]const SymbolTag = null,
    /// The name of the symbol containing this symbol. This information is for
    /// user interface purposes (e.g. to render a qualifier in the user interface
    /// if necessary). It can't be used to re-infer a hierarchy for the document
    /// symbols.
    containerName: ?[]const u8 = null,
    pub fn jsonStringify(self: @This(), w: *std.json.Stringify) std.json.Stringify.Error!void {
        return json.writeStruct(self, w, &.{});
    }
};

/// @since 3.16.0
///
/// Since LSP 3.16.0.
pub const CallHierarchyClientCapabilities = struct {
    /// Whether implementation supports dynamic registration. If this is set to `true`
    /// the client supports the new `(TextDocumentRegistrationOptions & StaticRegistrationOptions)`
